import { transformersEmbedder } from "@sweberdev/cosine"; import { buildDirectory } from "@sweberdev/cosine/node";
await buildDirectory("docs", "public/cosine", { baseUrl: "/docs", embedder: transformersEmbedder({ model: "english" }), exclude: ["drafts/"], });
buildIndex(documents, options) from @sweberdev/cosine takes documents from anywhere (a CMS, a database) and also runs in the browser.

Copy the model files (config.json, tokenizer.json, tokenizerconfig.json, onnx/modelquantized.onnx) from the model page to e.g. public/models/Xenova/all-MiniLM-L6-v2/, then point transformers.js there:
import { Cosine, loadIndex, transformersEmbedder } from "@sweberdev/cosine";
const embedder = transformersEmbedder({ model: "english", load: async () => { const transformers = await import("@huggingface/transformers"); transformers.env.allowRemoteModels = false; transformers.env.localModelPath = "/models/"; return transformers; }, }); const cosine = await loadIndex("/cosine/cosine-index.json", { embedder }); document.querySelector("cosine-search").cosine = cosine;
The ONNX runtime itself (WebAssembly) is loaded from a CDN by transformers.js; set transformers.env.backends.onnx.wasm.wasmPaths to serve it yourself as well.

import { CosineSearch } from "@sweberdev/cosine-react"; import { useRouter } from "next/navigation";
export function DocsSearch() { const router = useRouter(); return ( <CosineSearch index="/cosine/cosine-index.json" lang="de" shortcut="mod+k" onSelect={(result) => { router.push(result.chunk.url); return false; // Cosine does not navigate itself }} /> ); }
CosineSearch renders the web component, so attributes, styling and accessibility are the same.

import { useCosine, useCosineSearch } from "@sweberdev/cosine-react"; import { useState } from "react";
export function Search() { const { cosine, status } = useCosine("/cosine/cosine-index.json"); const [query, setQuery] = useState(""); const { results } = useCosineSearch(cosine, query, { limit: 5, groupByPage: true });
return ( <> <input value={query} onChange={(e) => setQuery(e.target.value)} onFocus={() => cosine?.warmup()} /> {status === "loading-model" && <p>Loading smart search…</p>} <ul> {results.map((r) => ( <li key={r.chunk.id}> <a href={r.chunk.url}>{[r.chunk.title, ...r.chunk.headings].join(" › ")}</a> <p>{r.snippet}</p> </li> ))} </ul> </> ); }
useCosineSearch returns keyword results on every keystroke and switches to the hybrid ranking as soon as the model is ready.

Custom properties:
cosine-search { --cosine-accent: #d4380d; --cosine-bg: #fff; --cosine-text: #111; --cosine-muted: #555; --cosine-border: #ddd; --cosine-radius: 6px; --cosine-max-height: 70vh; --cosine-z: 100; }
For more control, style the parts: ::part(input), ::part(results), ::part(result), ::part(result-title), ::part(result-snippet), ::part(status), ::part(shortcut).

import { test } from "@playwright/test"; import { expectAccessible } from "@sweberdev/surjection/playwright";
for (const path of ["/", "/shop", "/checkout"]) { test(`${path} is accessible`, async ({ page }) => { await page.goto(path); await expectAccessible(page, { failOn: "serious", locale: "de" }); }); }
Check states that only exist after interaction the same way: open the menu, the dialog or the error state first, then call expectAccessible.

Screen readers do not notice content that changes without a page load, such as "3 results" after filtering or "Added to cart". useAnnounce reads such messages out (WCAG 4.1.3).
import { AnnouncerProvider, useAnnounce } from "@sweberdev/surjection-react";
function Filter() { const announce = useAnnounce(); return <button type="button" onClick={() => announce("3 Ergebnisse gefunden")}>Filtern</button>; }
<AnnouncerProvider> <Filter /> </AnnouncerProvider>
Use announce(message, "assertive") only for errors that need immediate attention.

Many services covered by the European Accessibility Act have to explain how they meet the accessibility requirements, and most public bodies have to publish an accessibility statement. Surjection generates a structured statement as Markdown and HTML.
import { enforcementBodies, generateStatement } from "@sweberdev/surjection";
const { markdown, html } = generateStatement({ locale: "de", organisation: "Muster GmbH", scope: "www.muster.de", serviceDescription: "Online-Shop für Haushaltswaren mit Kundenkonto und Bestellverlauf.", status: "partial", knownIssues: [ { description: "Ältere PDF-Rechnungen sind nicht getaggt.", reason: "Auf Anfrage senden wir die Rechnung als barrierefreies Dokument.", plannedFix: "2027-03-31", }, ], method: "self", preparedOn: "2026-10-05", contact: { email: "barrierefreiheit@muster.de", phone: "+49 30 123456" }, enforcement: enforcementBodies.DE, });
Or from the command line with the same data as JSON:
npx surjection statement --config statement.json --out erklaerung.html
The output extension decides the format: .html writes HTML, anything else Markdown.

import "@sweberdev/surjection/vitest";
export default defineConfig({ test: { environment: "jsdom", setupFiles: ["./vitest.setup.ts"] }, });
import { render } from "@testing-library/react";
it("is accessible", async () => { const { container } = render(<SaveButton />); await expect(container).toBeAccessible(); });
The matcher switches off page-level rules (landmarks, a main heading) that make no sense for a single component. It accepts the same options as Playwright.
jsdom does not render CSS, so colour contrast cannot be checked here. Cover it with the Playwright helper or the CLI.

Surjection Pro adds what an agency needs to hand accessibility work to a client. It builds on the results.json that surjection check --out-json writes, so the free package stays the engine.
Package | What it does
@weber-development/surjection-report | Client report as HTML or PDF with your logo and colour, in German, Swiss German, French, Italian and English @weber-development/surjection-history | Records every run per project and renders a dashboard with status, change and trend @weber-development/surjection-checklist | The 55 WCAG 2.2 A/AA success criteria with instructions for manual testing, a browser editor and export to the accessibility statement

The packages are delivered through GitHub Packages. After purchase you get read access to the repository Weber-Development/surjection-pro-dist, which contains the full installation guide. In short:
@weber-development:registry=https://npm.pkg.github.com //npm.pkg.github.com/:_authToken=${SURJECTION_PRO_TOKEN}
npm i -D @sweberdev/surjection @weber-development/surjection-report @weber-development/surjection-history @weber-development/surjection-checklist
SURJECTIONPROTOKEN is a classic GitHub token with only the read:packages scope. Never commit it.

interface PageResult { url: string; title: string | undefined; testedAt: string; findings: Finding[]; passedRules: number; incomplete: Finding[]; // needs manual review }
interface Finding { rule: string; // axe-core rule id, e.g. "image-alt" impact: "minor" | "moderate" | "serious" | "critical"; help: string; helpUrl: string; criteria: { id: string; level?: "A" | "AA" | "AAA"; en301549: string }[]; bestPractice: boolean; nodes: { target: string; html: string; summary: string }[]; }
interface ResultsFile { version: 1; project?: string; createdAt: string; pages: PageResult[]; }
